class Solution {
public:
    int maximumXorProduct(long long a, long long b, int n) {
        long long MOD = 1e9 + 7;
        for (int i = n - 1; i >= 0; i--) {
            long long bit = 1LL << i;
            if ((min(a, b) & bit) == 0) {
                a ^= bit;
                b ^= bit;
            }
        }
        return (a % MOD) * (b % MOD) % MOD;
    }
};

class Solution {
    public int maximumXorProduct(long a, long b, int n) {
        long MOD = 1_000_000_007L;
        for (int i = n - 1; i >= 0; i--) {
            long bit = 1L << i;
            if ((Math.min(a, b) & bit) == 0) {
                a ^= bit;
                b ^= bit;
            }
        }
        return (int) (((a % MOD) * (b % MOD)) % MOD);
    }
}

